// Gemini giả để test: trả lời theo dữ liệu trong prompt
const body = $input.first().json.body || {};
const prompt = (body.contents || []).map((c) => (c.parts || []).map((p) => p.text || '').join('')).join('\n');
const dm = prompt.match(/<<<DU_LIEU\n([\s\S]*?)\nDU_LIEU>>>/);
const data = dm ? JSON.parse(dm[1]) : {};
const mm = prompt.match(/TIN NHẮN KHÁCH: (".*")/);
const msg = mm ? JSON.parse(mm[1]) : '';
const hasFeedback = prompt.includes('GÓP Ý TỪ BƯỚC SOÁT');
const wrong = msg.includes('SAI_HAI_LAN') || (msg.includes('THU_VIET_LAI') && !hasFeedback);
const fmt = (v) => String(v).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'đ';
let reply = 'Dạ shop có thể giúp gì thêm cho anh/chị ạ?', skus = [];
const ps = data.san_pham || [];
if (ps.length) {
  const p = ps[0];
  reply = `Dạ ${p.name} giá ${fmt(wrong ? p.price + 10000 : p.price)}, hiện còn ${p.stock} cái ạ.`;
  skus = [p.sku];
  const u = (data.goi_y_mua_kem || [])[0];
  if (u) { reply += ` Anh/chị có thể mua kèm ${u.name} giá ${fmt(u.price)} ạ.`; skus.push(u.sku); }
} else if (data.don_hang && data.don_hang.status) {
  reply = `Dạ đơn ${data.don_hang.tiktok_order_id} đang ở trạng thái ${data.don_hang.status} ạ.`;
}
const out = { reply, skus, need_human: msg.includes('XIN_GAP_NGUOI'), reason: 'gemini-gia' };
return [{ json: { candidates: [{ content: { role: 'model', parts: [{ text: JSON.stringify(out) }] } }], modelVersion: 'gemini-gia' } }];
